    const origin = c.req.header('Origin');
    if (origin && origin !== new URL(c.req.url).origin) {
      return c.json(
        { ok: false, error: 'foreign origin rejected', code: 'MCP_ORIGIN_REJECTED' },
        403
      );
    }
    return handleMcpRequest(c.req.raw);
  };
  app.all('/mcp', mcpHandler);
  app.all('/mcp/*', mcpHandler);

  return app;
}

